styl:
.b-new-hero-10 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-new-hero-10 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-new-hero-10 {  background: url("https://fsms.quadcode.com/storage/public/d6/26/tn7vhhgea139ulh0/rfm-331-background.png") center no-repeat;
  background-size: cover;
  background-color: #000;  }
.brad-full.b-new-hero-10 {  border-radius: 32px !important;  }
.b-new-hero-10 .w280 {  width: 100%;
  max-width: 280px;  }
@media screen and (max-width: 600px) {
  .b-new-hero-10 .w280 {  max-width: 100% !important;  }
}
.b-new-hero-10 .butt-link {  font-size: 18px;
  line-height: 27px;
  font-weight: 700;
  text-transform: none;
  text-decoration: none;
  color: #f9f9f9;
  display: block;
  padding: 16px 0 16px;
  text-align: center;
  letter-spacing: 0px;  }
.b-new-hero-10 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 40px;
  line-height: 50px;
  color: #fff;
  word-break: break-word;  }
@media screen and (max-width: 600px) {
  .b-new-hero-10 .white-title {  font-size: 26px !important;
    line-height: 32px !important;  }
}
.b-new-hero-10 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;
  padding-right: 20px;  }
@media screen and (max-width: 600px) {
  .b-new-hero-10 .white-text {  padding-right: 0 !important;  }
}
.b-new-hero-10 .pb16 {  padding-bottom: 16px;  }
.b-new-hero-10 .h-24 {  font-size: 8px;
  line-height: 24px;
  height: 24px;  }
.b-new-hero-10 u+.body .gmail-blend-screen {  background:#000;mix-blend-mode:screen  }
.b-new-hero-10 u+.body .gmail-blend-diff {  background:#000;mix-blend-mode:difference  }
.b-new-hero-10 .bgr, .bgr-image.b-new-hero-10 {  background-size:cover  }
.bgr-image.b-new-hero-10 {  background:url(https://fsms.quadcode.com/storage/public/d6/26/tn7vhhgea139ulh0/rfm-331-background.png) center no-repeat;background-color:#000  }
.brad-full.b-new-hero-10, .b-new-hero-10 .brad-full-32 {  border-radius:32px!important  }
.b-new-hero-10 .w280 {  width:100%;max-width:280px  }
@media screen and (max-width:600px) {
  .b-new-hero-10 .w280 {  max-width:100%!important  }
}
.b-new-hero-10 .butt-link, .b-new-hero-10 .butt-link-2 {  font-size:18px;font-weight:700;text-transform:none;text-decoration:none;color:#2f3749;display:block;line-height:27px;padding:16px 0;text-align:center;letter-spacing:0  }
.b-new-hero-10 .butt-link {  color:#f9f9f9  }
.b-new-hero-10 .white-title {  font-family:Helvetica!important;font-weight:700;font-size:40px;line-height:50px;color:#fff;word-break:break-word  }
@media screen and (max-width:600px) {
  .b-new-hero-10 .white-title {  font-size:26px!important;line-height:32px!important  }
}
.b-new-hero-10 .white-text {  font-family:Helvetica!important;font-style:normal;font-weight:400;font-size:18px;line-height:27px;color:#fff;padding-right:20px  }
@media screen and (max-width:600px) {
  .b-new-hero-10 .white-text {  padding-right:0!important  }
}
.b-new-hero-10 .pb16 {  padding-bottom:16px  }
.b-new-hero-10 .h-16, .b-new-hero-10 .h-20, .b-new-hero-10 .h-24 {  font-size:8px;line-height:16px;height:16px  }
.b-new-hero-10 .h-20, .b-new-hero-10 .h-24 {  line-height:20px;height:20px  }
.b-new-hero-10 .h-24 {  line-height:24px;height:24px  }
